window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["36"]={"https://www.gov.uk/foreign-travel-advice/bangladesh":{"r":"govuk","at":"2026-11-17T16:16Z","sha":"8ae49a406a740fb584468bdab0048592d52c86611935cf0a51433def391f1f26","read":"https://www.gov.uk/api/content/foreign-travel-advice/bangladesh","bytes":101535,"x":"fulltext v1","title":"Bangladesh travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-03-15T00:00:00+00:00","mod":"2026-10-22T09:30:24+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against all but essential travel"]},{"k":"p","s":["FCDO advises against all but essential travel to the Chittagong Hill Tracts, an area made up of the districts of:"]},{"k":"li","s":["Rangamati"]},{"k":"li","s":["Khagrachari"]},{"k":"li","s":["Bandarban"]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/bangladesh/safety-and-security"],"."]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/pakistan/british-high-commission-islamabad"]," including in an emergency."]},{"k":"h","s":["Flooding"]},{"k":"p","s":["Flash floods and landslides have affected parts of Bangladesh, including the Chittagong Hill Tracts, Cox’s Bazar and Sylhet regions."]},{"k":"p","s":["There is an increased risk of seasonal flooding in parts of northeast Bangladesh, including the Sylhet region, due to heavy rainfall during the pre‑monsoon period."]},{"k":"p","s":["Flooding may occur with little warning and could disrupt transport, utilities and access to services, particularly in low‑lying and river‑adjacent areas."]},{"k":"p","s":["Monitor local weather forecasts and updates from the ",["Bangladesh Flood Forecasting and Warning Centre","https://ffwc.gov.bd/app/flood-summary"]," and the ",["Bangladesh Meteorological Department","https://live8.bmd.gov.bd/"]," and follow the advice of local authorities."]},{"k":"h","s":["Global travel impacts due to escalation in the Middle East"]},{"k":"p","s":["Escalation in the Middle East has caused widespread travel disruption, including airspace closures, delayed and cancelled flights."]},{"k":"p","s":["Your travel plans may be affected, even if your destination is not in the Middle East. Before you travel:"]},{"k":"li","s":["check travel advice for any countries or territories you are transiting through"]},{"k":"li","s":["check for the latest updates from your airline or tour operator"]},{"k":"li","s":["review your travel insurance policy for coverage"]},{"k":"li","s":["monitor local and international media for the latest information and sign up for travel advice email alerts."]},{"k":"h","s":["Energy and fuel shortages"]},{"k":"p","s":["Bangladesh is facing energy and fuel shortages linked to global supply disruptions. The authorities have announced measures including limits on fuel sales. This may lead to transport disruption and delays in some areas. You should plan ahead, allow extra time for travel and keep up to date with local media."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/bangladesh/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Bangladesh’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Bangladesh set and enforce entry rules. If you are not sure how these requirements apply to you, contact the ",["Bangladeshi High Commission in the UK","https://bhclondon.org.uk/"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Bangladesh, your passport must have at least 2 blank pages and no damage."]},{"k":"p","s":["See ‘Applying for a visa’ for passport validity requirements for visas."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet the requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"p","s":["Make sure you get your passport stamped."]},{"k":"p","s":["Make sure you get an entry stamp in your passport when you arrive. Immigration officers will check the date on your entry stamp when you leave Bangladesh. You could get a fine for overstaying."]},{"k":"p","s":["At Bangladeshi border control, you may also need to show a return or onward ticket."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Electronic arrival and departure cards"]},{"k":"p","s":["Bangladesh has introduced online arrival and departure registration for foreign nationals. Travellers may be required to complete an ",["electronic arrival card","https://edcard.specialbranch.gov.bd/foreigner/register"]," before entering Bangladesh and an ",["electronic departure card","https://edcard.specialbranch.gov.bd/foreigner/departure"]," before leaving."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to visit Bangladesh for up to 3 months, unless you have a ‘no visa required’ stamp in your UK passport."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":["If you are eligible for a visa on arrival, you may be able to ",["pre-register online","https://voa.specialbranch.gov.bd/register/new"]," before travel. Check the latest requirements with the Bangladeshi authorities and your airline before travelling."]},{"k":"p","s":[["Apply in advance for a visa","https://bhclondon.org.uk/visa"]," from the Bangladeshi High Commission in the UK."]},{"k":"p","s":["Your passport must have an ‘expiry date’ at least 6 months after the date your visa starts. The visa starts from the date of issue, not the date of travel. If you plan to use Bangladesh as a hub to visit other countries in the region, make sure you get a multiple-entry visa."]},{"k":"p","s":["The Visa on Arrival service continues to operate, including in the period before the national elections on 12 February. See ",["Checks at the border","https://www.gov.uk/foreign-travel-advice/bangladesh/entry-requirements#checks-at-the-border"],"."]},{"k":"p","s":["You may be able to ",["apply for a visa on arrival at Dhaka airport","https://bhclondon.org.uk/visa-on-arrival"],". You must have a return ticket and proof of funds to apply for a visa on arrival. Visas on arrival are:"]},{"k":"li","s":["single entry"]},{"k":"li","s":["valid for 15 to 30 days"]},{"k":"li","s":["not guaranteed – Bangladeshi immigration officers issue them at their discretion"]},{"k":"li","s":["also available for business travel if you have a letter of introduction"]},{"k":"p","s":["If you want to stay longer, you can ",["apply for a visa extension from the Department of Immigration and Passports","https://dip.gov.bd/"],"."]},{"k":"hs","s":["Working in Bangladesh"]},{"k":"p","s":["If you are working in Bangladesh, you must get a work permit, and you’ll need an Income Tax Clearance Certificate or an Income Tax Exemption Certificate before leaving Bangladesh. You get application forms from the ",["National Board of Revenue, Bangladesh","https://nbr.gov.bd/form/income-tax/eng"],"."]},{"k":"hs","s":["‘No visa required’ stamp"]},{"k":"p","s":["British nationals of Bangladeshi origin may be eligible to ",["apply for a ‘no visa required’ stamp","https://bhclondon.org.uk/no-visa-required-old"]," from the Bangladeshi High Commission in the UK."]},{"k":"h","s":["Checks at the border"]},{"k":"p","s":["During the election period, you may face further checks at the border and be asked for additional documents such as:"]},{"k":"li","s":["proof of an onward or return ticket"]},{"k":"li","s":["confirmation of accommodation"]},{"k":"li","s":["contact details"]},{"k":"p","s":["Check with your travel operator for the latest information before travelling."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To enter Bangladesh, you must have certificates to prove you’ve had:"]},{"k":"li","s":["a yellow fever vaccination if you’re coming from a ",["country listed as a transmission risk","https://nathnacyfzone.org.uk/factsheet/65/countries-with-risk-of-yellow-fever-transmission"]]},{"k":"li","s":["a polio vaccine, in certain circumstances"]},{"k":"p","s":["For full details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Bangladesh guide","https://travelhealthpro.org.uk/country/22/bangladesh#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about goods you can take into or out of Bangladesh. You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking money into or out of Bangladesh"]},{"k":"p","s":["You may need to declare foreign currency or Bangladeshi taka, depending on the amount you are travelling with."]},{"k":"p","s":["You can cash travellers cheques at banks and airports. ATMs are available in most urban areas and accept UK cards. There are fewer ATMs in rural areas."]},{"k":"h","s":["Safety and security"]},{"k":"p","s":["This guide also has safety advice for ",["regions of Bangladesh","https://www.gov.uk/foreign-travel-advice/bangladesh/regional-risks"],"."]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Bangladesh"]},{"k":"p","s":["Terrorists are very likely to try to carry out attacks in Bangladesh."]},{"k":"p","s":["Terrorists are very likely to try to carry out attacks. These attacks could be indiscriminate, including in places visited by foreign nationals, and places such as:"]},{"k":"li","s":["public buildings, including restaurants and cafés"]},{"k":"li","s":["public transport"]},{"k":"li","s":["crowded areas"]},{"k":"li","s":["religious buildings"]},{"k":"li","s":["political rallies"]},{"k":"p","s":["Some groups have targeted people who they consider to have views and lifestyles contrary to Islam, including religious minorities."]},{"k":"p","s":["Islamist extremist groups operate in Bangladesh."]},{"k":"p","s":["The Bangladeshi authorities continue to disrupt planned attacks. Increases in security force presence and restrictions on movement may be put in place at short notice."]},{"k":"p","s":["Remain aware of your surroundings. Avoid large gatherings and other locations with a police or security presence. Follow the advice of local authorities."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["Bangladesh held national elections on 12 February 2026. Political rallies and demonstrations can quickly turn violent leading to clashes. During demonstrations and strikes (‘hartals’), there can be arson, violence and vandalism in towns and cities across the country, which can result in fatalities."]},{"k":"p","s":["There have been occasional attacks against minority religious communities."]},{"k":"p","s":["There have also been attacks targeting the police and security forces. These have included improvised explosive device (IED) attacks in major cities."]},{"k":"p","s":["In July and August 2024, a popular uprising led to widespread violence across Bangladesh, with many deaths and injuries."]},{"k":"p","s":["Be alert to quickly changing situations on the streets. Stay away from protests or demonstrations, rallies and large gatherings. If you see a demonstration starting, move to a place of safety. Follow the advice of local authorities. Follow updates in local media and ",["get email notifications","https://www.gov.uk/foreign-travel-advice/bangladesh/email-signup"]," when this travel advice is updated."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Robbery and violence"]},{"k":"p","s":["There are reports of an increase in violent crime since the popular uprising in Bangladesh in July and August 2024."]},{"k":"p","s":["Criminal gangs operate in Dhaka and other cities. Thieves often work in pairs on motorcycles or motorised rickshaws known as ‘CNGs’."]},{"k":"p","s":["Potential threats include armed robbery, violent crime and rape."]},{"k":"p","s":["Passengers using rickshaws, taxis, buses or trains are vulnerable to violent crime, particularly at night. Avoid using public transport if you’re travelling alone. See ",["Transport risks","https://www.gov.uk/foreign-travel-advice/bangladesh/safety-and-security#transport-risks"],"."]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["Be alert when using and carrying your phone in public and crowded spaces. To reduce your risk, do not carry large quantities of money or wear expensive-looking jewellery or watches."]},{"k":"hs","s":["Sexual assault"]},{"k":"p","s":["There is a risk of sexual assault, including attacks on female foreign national visitors."]},{"k":"p","s":["Female travellers often experience verbal and physical harassment by individuals or groups of men. Avoid isolated areas when alone at any time of day. Be vigilant, particularly at night."]},{"k":"p","s":["See ",["advice for women travelling abroad","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"],"."]},{"k":"hs","s":["Methanol poisoning"]},{"k":"p","s":["There have been deaths and cases of serious illness caused by alcoholic drinks containing methanol in Bangladesh."]},{"k":"p","s":["Alcohol is strictly regulated in Bangladesh. Non-Muslim citizens over 21 and foreign visitors may drink in licensed venues with permits, while it is banned for Muslims except for medical reasons. These restrictions often lead people to seek alcohol from unlicensed sources, creating a black market, which can use methanol, and increasing the risk of methanol poisoning."]},{"k":"p","s":["Even small amounts of methanol can kill. It is not possible to identify methanol in alcoholic drinks by taste or smell. See ",["Travel Aware Drink Spiking and Methanol Poisoning","https://travelaware.campaign.gov.uk/spiking-and-methanol-poisoning/"]," for information about how to reduce the risks."]},{"k":"p","s":["Seek urgent medical attention if you or someone you are travelling with show the ",["signs of methanol poisoning","https://travelaware.campaign.gov.uk/spiking-and-methanol-poisoning/"]," after drinking."]},{"k":"hs","s":["Dhaka and Sylhet airports"]},{"k":"p","s":["Dhaka international and Sylhet airports are fully operational. Check with your travel provider for updates."]},{"k":"p","s":["Risks at Dhaka and Sylhet airports include:"]},{"k":"li","s":["theft, including passport theft"]},{"k":"li","s":["harassment"]},{"k":"li","s":["overcharging of taxi fees"]},{"k":"p","s":["To reduce your risk:"]},{"k":"li","s":["avoid touts offering to carry your bags"]},{"k":"li","s":["keep documents and belongings safe"]},{"k":"li","s":["arrange taxis in advance"]},{"k":"h","s":["Laws and cultural differences"]},{"k":"p","s":["Bangladesh is a majority Muslim country. Respect the customs and laws. Make sure your actions do not cause offence."]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Local officials may ask you for ID."]},{"k":"p","s":["Carry copies of the photo page in your passport and your Bangladeshi visa. Keep the originals somewhere safe and leave copies with friends or relatives in the UK."]},{"k":"hs","s":["Dress code"]},{"k":"p","s":["Both men and women should dress modestly to avoid causing offence. Women should cover their shoulders and legs in public."]},{"k":"hs","s":["Ramadan"]},{"k":"p","s":["Ramadan in 2026 is expected to start on the 17/18 February and last until the third week of March."]},{"k":"p","s":["Ramadan is a holy month for Muslims. Get advice on respecting Ramadan from your tour guide, hotel or business contacts."]},{"k":"p","s":["You should:"]},{"k":"li","s":["check opening hours of shops and restaurants"]},{"k":"li","s":["follow local dress codes – clothing that does not meet local dress codes may cause more offence at this time, both for women and men"]},{"k":"li","s":["be aware that fasting can cause tiredness, particularly during the later afternoon and early evening"]},{"k":"hs","s":["British nationals of Bangladeshi origin"]},{"k":"p","s":["If you’re a British national of Bangladeshi origin, the Bangladeshi government will consider you to be a Bangladeshi citizen, even if you:"]},{"k":"li","s":["have never had a Bangladeshi passport"]},{"k":"li","s":["were born outside of Bangladesh"]},{"k":"p","s":["This may limit the help the UK government can offer you. For more information on Bangladeshi nationality, check with the ",["Bangladeshi High Commission in the UK","https://bhclondon.org.uk/"],"."]},{"k":"p","s":["The ",["Bangladesh Police Expatriate Help Cell","https://www.police.gov.bd/en/expatriate_help_cell"]," offers services to foreign nationals, including dual nationals."]},{"k":"hs","s":["Alcohol laws"]},{"k":"p","s":["You may need a liquor permit to drink alcohol in Bangladesh. A liquor permit allows you to drink alcohol in government-licensed bars. Check the requirements at your local district office and apply for a permit if necessary."]},{"k":"hs","s":["Illegal drugs penalties"]},{"k":"p","s":["There are severe penalties for possessing and trafficking illegal drugs. Some drug-related offences are punishable by the death penalty or life imprisonment."]},{"k":"hs","s":["Prison sentences and conditions"]},{"k":"p","s":["If you break local laws, you may get a prison sentence, served in a local prison. Delays and inefficiency in the judicial system can result in long detentions until court hearings eventually take place. Prison conditions are far below UK standards."]},{"k":"p","s":["British nationals detained in Bangladesh have the right to request access to British High Commission officials."]},{"k":"hs","s":["Family law and property disputes"]},{"k":"p","s":["Family law in Bangladesh is very different from UK law. Always check your legal position when, for example, child custody is an issue."]},{"k":"p","s":["The British High Commission in Dhaka cannot help British nationals of Bangladeshi origin with land or property problems."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex sexual activity is illegal in Bangladesh."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Bangladesh, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You need a ",["1949 international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," and a UK driving licence to drive in Bangladesh. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"hs","s":["Driving standards"]},{"k":"p","s":["Road accidents are common in Bangladesh due to:"]},{"k":"li","s":["poor driving standards"]},{"k":"li","s":["many unlicensed and/or unroadworthy vehicles"]},{"k":"li","s":["large numbers of rickshaws on the roads"]},{"k":"p","s":["Driving at night is especially dangerous as many drivers do not use headlights or use undipped headlights. There is also a risk of robbery if you travel between towns after dark. Avoid driving alone at night."]},{"k":"hs","s":["Cycle rickshaws and taxis"]},{"k":"p","s":["Cycle rickshaws used on main roads alongside traffic are not safe – they offer little protection if there is an accident."]},{"k":"p","s":["Police are often unable to verify private hire drivers’ details, as driving records are often inaccurate."]},{"k":"p","s":["Ride-hailing apps like Uber are available in Bangladesh. Uber drivers generally only accept cash payment. To make sure you get in the right car safely:"]},{"k":"li","s":["wait in a safe location, not out on the street"]},{"k":"li","s":["match the car’s registration plate, make and model (registration plates are generally in Bangla and appear on Uber in English)"]},{"k":"li","s":["ask the driver to state your name"]},{"k":"li","s":["check the driver’s photo"]},{"k":"li","s":["share your journey details and consider enabling GPS tracking on your phone so trusted contacts can see your location"]},{"k":"hs","s":["Buses"]},{"k":"p","s":["The risks of travelling by bus include:"]},{"k":"li","s":["extremely poor maintenance and driving standards"]},{"k":"li","s":["lack of seat belts"]},{"k":"li","s":["frequent traffic collisions, some resulting in deaths"]},{"k":"li","s":["rape, sexual assaults and other crimes, sometimes committed by the bus crew"]},{"k":"p","s":["Avoid travelling by bus alone and at night."]},{"k":"hs","s":["Air travel"]},{"k":"p","s":["Due to the security situation in Bangladesh, there are frequent disruptions to air travel, often at short notice. Stay in touch with your airline. Security checks at the airport can also be slow."]},{"k":"hs","s":["Rail travel"]},{"k":"p","s":["The rail network is extensive but old and generally considered slow."]},{"k":"p","s":["Rail travel risks include:"]},{"k":"li","s":["frequent fatal accidents"]},{"k":"li","s":["flood-damaged bridges and culverts in dangerous condition"]},{"k":"li","s":["crime, including theft and sexual assault"]},{"k":"p","s":["On some trains, you may be able to lock first-class compartment doors. Make sure the door is locked if you’re travelling at night."]},{"k":"p","s":["For information see Bangladesh Railways."]},{"k":"hs","s":["Sea and river travel"]},{"k":"p","s":["River and sea ferry risks include:"]},{"k":"li","s":["dangerous overcrowding, particularly during religious holidays and other festivals"]},{"k":"li","s":["falsified safety certificates on some vessels"]},{"k":"li","s":["missing or inappropriate safety and survival equipment"]},{"k":"li","s":["lack of communication equipment"]},{"k":"li","s":["criminal gangs targeting vessels"]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/extreme-weather-and-natural-hazards"],"."]},{"k":"hs","s":["Monsoon season"]},{"k":"p","s":["The monsoon season runs from June to September and can cause widespread flooding and travel disruption."]},{"k":"p","s":["If travelling, you should check:"]},{"k":"li","s":["access routes"]},{"k":"li","s":["weather updates from the Bangladesh Meteorological Department"]},{"k":"li","s":["the advice of local authorities"]},{"k":"hs","s":["Tropical cyclones"]},{"k":"p","s":["There is a risk of tropical cyclones in Bangladesh. Check weather reports from the Bangladesh Meteorological Department and the ",["World Meteorological Organization","https://severeweather.wmo.int/tc/in/index.html"],"."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["Around half of Bangladesh, including the cities of Moulvibazar and Sylhet, is in a high-risk earthquake zone. Other areas, including Dhaka, are at moderate risk. Tremors and earthquakes, usually minor ones, happen occasionally."]},{"k":"p","s":["The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"hs","s":["Tsunamis"]},{"k":"p","s":["Bangladesh can be affected by tsunamis. In some cases the Bangladeshi government will issue tsunami warnings. Monitor local news and follow any advice given by local authorities."]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Bangladesh. It only covers regions where FCDO has specific advice."]},{"k":"p","s":["You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/bangladesh/warnings-and-insurance"]," and ",["safety and security advice","https://www.gov.uk/foreign-travel-advice/bangladesh/safety-and-security"],"."]},{"k":"h","s":["Chittagong Hill Tracts"]},{"k":"p","s":["FCDO advises against all but essential travel to the Chittagong Hill Tracts, an area made up of the districts of:"]},{"k":"li","s":["Rangamati"]},{"k":"li","s":["Khagrachari"]},{"k":"li","s":["Bandarban"]},{"k":"p","s":["Chittagong City and other districts of Chittagong Division are not included in the travel warning."]},{"k":"p","s":["Security in the Chittagong Hill Tracts is a cause for concern. There are regular reports of violence and other criminal activity, particularly in more remote areas."]},{"k":"p","s":["If you plan to travel to the Chittagong Hill Tracts, you must give the Bangladesh authorities 10 days’ notice."]},{"k":"p","s":["Contact:"]},{"k":"li","s":["Chittagong Divisional Commissioner’s Office (Telephone: 031 615 247)"]},{"k":"li","s":["Chittagong Deputy Commissioner’s Office (Telephone: 031 619 996)"]},{"k":"h","s":["Bangladesh-Myanmar border"]},{"k":"p","s":["There are ongoing reports of increasing violence and fighting in Myanmar, close to the Bangladesh border. The situation in border areas near Myanmar remains unpredictable and may deteriorate at short notice. You should monitor local news outlets closely."]},{"k":"p","s":["Continuing violence has resulted in hundreds of thousands of Rohingya refugees crossing into the south-east of Bangladesh."]},{"k":"p","s":["Most of the refugees are in the subdistricts of Ukhia and Teknaf in the southern part of Cox’s Bazar district. There are regular reports of insecurity, protests and violence."]},{"k":"p","s":["Teknaf has the highest level of drug-related gang violence across Bangladesh, including:"]},{"k":"li","s":["murders and shooting incidents between the gangs and police"]},{"k":"li","s":["drug seizures, including large amounts of yaba (a mixture of caffeine and methamphetamine)"]},{"k":"li","s":["kidnappings"]},{"k":"p","s":["Violence has increased in the refugee camps. There is no sign that foreign nationals are being targeted."]},{"k":"p","s":["If you plan to visit Ukhia and Teknaf, you should:"]},{"k":"li","s":["use caution"]},{"k":"li","s":["consult the local authorities – you may need permission to travel there"]},{"k":"li","s":["work through humanitarian agencies recognised by the Bangladeshi government if you want to provide assistance"]},{"k":"h","s":["Bangladesh-India border"]},{"k":"p","s":["Take particular care near the border with India. There are regular reports of individuals being killed for illegally crossing the border. There are occasional skirmishes between the Indian and Bangladeshi border guards, including exchanges of gunfire."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," and access to money for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 999 and ask for an ambulance."]},{"k":"p","s":["If you suspect a heart attack, ask for a ‘cardiac ambulance’."]},{"k":"p","s":["It may be faster to travel to the nearest hospital yourself if you have a vehicle."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccination recommendations for Bangladesh","https://travelhealthpro.org.uk/country/22/bangladesh#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Bangladesh","https://travelhealthpro.org.uk/country/22/bangladesh"],", including:"]},{"k":"li","s":["dengue fever, a mosquito-borne disease that can occur year-round but is more widespread during the rainy season, May to September"]},{"k":"li","s":["other mosquito-borne diseases, including malaria, chikungunya and Zika virus"]},{"k":"li","s":["severe air pollution, especially from November to March"]},{"k":"p","s":["Dengue cases are increasing, including in Dhaka. See ",["insect bite avoidance advice on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/38/insect-and-tick-bite-avoidance"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"p","s":["You should carry any medical papers or prescriptions and be prepared to answer questions if police ask you about any medication you’re carrying."]},{"k":"h","s":["Healthcare in Bangladesh"]},{"k":"p","s":["Medical facilities in Bangladesh are poor. Routine tests and X-rays are unreliable."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Bangladesh","https://www.gov.uk/government/publications/bangladesh-list-of-medical-facilities"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Bangladesh"]},{"k":"p","s":["Telephone: 999 (ambulance, fire, police)"]},{"k":"h","s":["Expatriate Help Cell"]},{"k":"p","s":["The ",["Bangladesh Police Expatriate Help Cell","https://www.police.gov.bd/en/expatriate_help_cell"]," offers services to expatriates, including dual nationals."]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Bangladesh"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Bangladesh"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Bangladesh"]," in Bangladesh"]},{"k":"li","s":["dealing with a ",["death in Bangladesh","https://www.gov.uk/government/publications/bereavement-information-pack-bangladesh"]]},{"k":"li","s":["being ",["arrested in Bangladesh","https://www.gov.uk/government/publications/bangladesh-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/bangladesh/british-high-commission-dhaka"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/bangladesh/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Bangladesh","https://www.gov.uk/government/publications/overseas-business-risk-bangladesh"]," on how to manage political, economic, and business security-related risks."]}],"chars":24628,"change":"Removal of information about Hindu festival of Durga Puja (‘Warnings and insurance’ page)."},"https://www.gov.uk/foreign-travel-advice/iraq":{"r":"govuk","at":"2026-11-17T16:47Z","sha":"464c51d5e492d0a0c133e16a98744a3ed244074016eabbb2883af84241290017","read":"https://www.gov.uk/api/content/foreign-travel-advice/iraq","bytes":78228,"x":"fulltext v1","title":"Iraq travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-03-20T00:00:00+00:00","mod":"2026-10-27T16:06:23+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against travel"]},{"k":"hs","s":["Federal Iraq"]},{"k":"p","s":["FCDO advises against all travel to:"]},{"k":"li","s":["The parts of Anbar province which are west of, but not including Ramadi City"]},{"k":"li","s":["Diyala province except for Baqubah City"]},{"k":"li","s":["Kirkuk province"]},{"k":"li","s":["Ninawa province"]},{"k":"li","s":["Salah al-Din province"]},{"k":"li","s":["Jurf al-Sakr town in Babil province"]},{"k":"li","s":["Sadr City, part of Baghdad province"]},{"k":"li","s":["Within 5km of areas that border Iran in Wasit, Maysan and Basra provinces"]},{"k":"li","s":["Within 5km of Iraq’s borders with Saudi Arabia and Kuwait"]},{"k":"p","s":["FCDO advises against all but essential travel to:"]},{"k":"li","s":["The remainder of Al-Muthanna province"]},{"k":"li","s":["Al-Qadasiyah province"]},{"k":"li","s":["The remainder of Anbar province"]},{"k":"li","s":["Babil province (except Jurf al-Sakr town)"]},{"k":"li","s":["Baghdad province (except Sadr City)"]},{"k":"li","s":["The remainder of Basra province, including Highways 1 and 8 and the Safwan-Kuwait border crossing"]},{"k":"li","s":["Dhi Qar Province"]},{"k":"li","s":["Karbala Province"]},{"k":"li","s":["The remainder of Maysan province"]},{"k":"li","s":["The remainder of Najaf province"]},{"k":"li","s":["The remainder of Wasit province"]},{"k":"li","s":["Baqubah City in Diyala province"]},{"k":"li","s":["The road sections of Highway 34 between Baghdad and Baqubah, and Highway 2 between Baqubah and Erbil"]},{"k":"hs","s":["Kurdistan Region of Iraq"]},{"k":"p","s":["FCDO advises against all but essential travel to the Kurdistan Region of Iraq"]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/iraq/regional-risks"],"."]},{"k":"h","s":["Consular support"]},{"k":"p","s":["Consular support is severely limited in areas where FCDO advises against travel."]},{"k":"h","s":["Regional tensions"]},{"k":"p","s":["The context in the Middle East remains deeply unpredictable and the risk of sudden escalation is high. Since conflict began in early 2026, Iran has stated its intention to target locations associated with the US and Israel, including, but not limited to, organisations, businesses, facilities, and institutions. There have been strikes and retaliatory attacks by Iran and others across the region against civilian and US military infrastructure."]},{"k":"p","s":["British nationals in, or planning to travel through, the Middle East should be prepared for possible flight cancellations, airspace closures, and travel disruptions. You should:"]},{"k":"li","s":["read ",["If you’re affected by a crisis abroad - GOV.UK","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],". This includes guidance on “how to prepare for a crisis” with suggestions on what you might include in your emergency supplies and “what to do in a crisis”"]},{"k":"li","s":["sign up to FCDO Travel Advice ",["email alerts","https://www.gov.uk/foreign-travel-advice/iraq/email-signup"]]},{"k":"li","s":["follow advice from the local authorities"]},{"k":"li","s":["monitor local and international media for the latest information, including updates relating to airports and airspace which could close at short notice"]},{"k":"li","s":["stay away from areas around security or military facilities"]},{"k":"li","s":["keep your departure plans under review, and ensure your travel documents are up to date"]},{"k":"li","s":["if advised to take shelter, stay indoors or find the nearest safe building or designated shelter. An interior stairwell or a room with as few external walls or windows as possible may provide additional protection. The greatest risk is from falling debris caused by intercepts, and you are safest inside a secure structure. Do not approach or touch any drone or missile fragments or unusual objects"]},{"k":"h","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel despite FCDO advice, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/iraq/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK who choose to travel despite FCDO advice. It is based on the UK government’s understanding of Iraq’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Iraq set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Iraqi Embassy in the UK","https://mofa.gov.iq/london/en/embassy-of-the-republic-of-iraq-in-london/"],"."]},{"k":"h","s":["Entry to Saudi Arabia"]},{"k":"p","s":["British nationals who are trying to leave Iraq via Saudi Arabia and who are travelling on British Emergency Travel Documents, Emergency Passports, or passports with less than 6 months remaining validity, should call the helplines for British Embassy Riyadh +966 (0) 11481 9100 or British Consulate Jeddah +966 (0)126225550 for advice."]},{"k":"p","s":["See ",["‘Entry requirements’ for Saudi Arabia","https://draft-origin.publishing.service.gov.uk/foreign-travel-advice/saudi-arabia/entry-requirements"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Iraq, your passport must have an ‘expiry date’ at least 6 months after the date you arrive and have at least one blank page."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to visit Iraq."]},{"k":"p","s":["You are no longer able to get a visit visa on arrival in Iraq. You must apply for a visa on the ",["e-visa portal of the Government of Iraq","https://eservice.evisa.iq/"]," at least 24 hours before you travel. The visa costs $160 and is valid for 60 days. Ensure that you have a return ticket in place or a ticket out of Iraq to a third destination. Without such a ticket in place, there is a risk of the airline refusing boarding."]},{"k":"hs","s":["e-visa for Kurdistan Region"]},{"k":"p","s":["The government of the Kurdistan Region of Iraq (KRI) has introduced a new e-visa process. You can find the details and apply on the ",["e-visa portal of the Kurdistan Region Government","https://visit.gov.krd/"],". It is also possible to obtain a visa on arrival. Both types of visas are valid for travel in KRI only."]},{"k":"h","s":["Weapon Authority Cards"]},{"k":"p","s":["Make sure you have the right documents when you arrive in Iraq, including Weapon Authority Cards (WAC) if you are carrying weapons."]},{"k":"p","s":["Foreign nationals have been arrested for failing to provide the correct documentation when requested."]},{"k":"h","s":["HIV and hepatitis test"]},{"k":"p","s":["You must have a blood test for HIV and hepatitis unless you’re travelling on a visit visa. You must take the test within 10 days of arrival and repeat it every 90 days while you’re in Iraq. Guidance on where to go for the blood test is available at the airport when you arrive."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about goods you can take into or out of Iraq. You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking money into or out of Iraq"]},{"k":"p","s":["On entering or exiting Iraq, you must declare:"]},{"k":"li","s":["all local currency over 200,000 Iraqi dinars"]},{"k":"li","s":["all currency or items valued over 10,000 US Dollars or the same value in any other foreign currency"]},{"k":"h","s":["Safety and security"]},{"k":"p","s":["This guide also has additional safety advice for ",["regions of Iraq","https://www.gov.uk/foreign-travel-advice/iraq/regional-risks"],"."]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Iraq"]},{"k":"p","s":["Terrorists are very likely to try to carry out attacks in Iraq."]},{"k":"p","s":["Attacks can occur throughout the country, including the Kurdistan region of Iraq, but are more frequent in areas where Daesh had a strong presence and capability. This includes parts of the provinces of:"]},{"k":"li","s":["Anbar"]},{"k":"li","s":["Diyala"]},{"k":"li","s":["Ninewah"]},{"k":"li","s":["Salah Al-Din"]},{"k":"li","s":["Tam’mim (Kirkuk)"]},{"k":"p","s":["Foreign nationals are high-value targets for terrorists, insurgents and criminals. Indiscriminate attacks against public places and Iraqi civilians also occur. Terrorist attacks could be indiscriminate, including in places visiting by foreign nationals, such as:"]},{"k":"li","s":["airports and public transport"]},{"k":"li","s":["land border crossings"]},{"k":"li","s":["markets, stores, hotels and restaurants"]},{"k":"li","s":["government buildings, political offices, police stations and military establishments"]},{"k":"li","s":["residential compounds"]},{"k":"li","s":["maritime facilities and oil facilities"]},{"k":"li","s":["religious sites and ceremonies"]},{"k":"li","s":["political events, large crowds"]},{"k":"li","s":["sports venues and stadiums"]},{"k":"li","s":["fake vehicle checkpoints"]},{"k":"p","s":["There is a heightened threat of attacks against western interests. While attacks can take place at any time, there’s a heightened threat during religious or public holidays. Militant groups opposed to a western presence pose a threat to UK and other interests in Iraq, including the Kurdistan Region."]},{"k":"p","s":["Methods of attack have included:"]},{"k":"li","s":["large-scale co-ordinated bombings designed to cause mass casualties"]},{"k":"li","s":["rockets and mortars"]},{"k":"li","s":["shootings"]},{"k":"li","s":["suicide bombs"]},{"k":"li","s":["vehicle bombs"]},{"k":"hs","s":["UK prosecution for terrorism offences"]},{"k":"p","s":["If you travel to Iraq to fight, and your activities amount to offences against UK terrorism legislation, you could be prosecuted on your return to the UK."]},{"k":"hs","s":["Terrorist kidnap"]},{"k":"p","s":["There is a high threat of kidnapping throughout Iraq."]},{"k":"p","s":["This includes both from Daesh and other terrorist and militant groups. Keep your security arrangements up-to-date and carefully plan any travel plans. Kidnappings can be for ideological reasons as well as financial or political gain."]},{"k":"p","s":["British nationals are seen as legitimate targets, including tourists, humanitarian aid workers, oil workers, journalists and business travellers. If you are kidnapped, the reason for your presence is unlikely to protect you or secure your safe release."]},{"k":"p","s":["The long-standing policy of the British Government is not to make substantive concessions to hostage takers. The British Government considers that paying ransoms and releasing prisoners builds the capability of terrorist groups and finances their activities. This can, in turn, increase the risk of further hostage-taking. The Terrorism Act (2000) makes payments to terrorists illegal."]},{"k":"h","s":["Security situation"]},{"k":"p","s":["Some areas of Iraq have experienced recent attack by artillery, drones and rockets. Coalition military installations continue to be a target, including in the Kurdistan Region. Iranian targeting of Iranian-Kurdish opposition groups within the KRI increased during the recent conflict."]},{"k":"p","s":["Intermittent strikes targeting these groups have continued since in areas across the KRI, including around Rawanduz and Koya. The risk of further strikes remains. Stay away from areas associated with these groups."]},{"k":"p","s":["The threat level may restrict UK government staff from travelling to certain areas."]},{"k":"p","s":["If you’re travelling to Iraq, take security precautions:"]},{"k":"li","s":["get advice from a private security company"]},{"k":"li","s":["make arrangements for secure accommodation and transport"]},{"k":"li","s":["have contingency plans in place"]},{"k":"li","s":["stay up to date with local media"]},{"k":"li","s":["consider pre-deployment training"]},{"k":"p","s":["The security situation may change at short notice. You may need to ‘shelter in place’ or hunker down for several days. Keep essential supplies, such as food, water and medicine where you are staying."]},{"k":"p","s":["Anti-British and anti-American sentiment can increase during political tension or because of long-running hostility from some Iraqi militias towards the Global Coalition Against Daesh. Protests or attacks may be directed towards British and American institutes or companies, or those which appear to be connected to Britain or the United States of America. Monitor local media to keep up to date with developments."]},{"k":"p","s":["In the event of widespread disturbances or a deterioration in the security situation, there may be limits to the help that FCDO can provide. Read further information and advice on ",["how to deal with a crisis overseas","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],"."]},{"k":"p","s":["Ensure your travel documents are up to date in case you need to leave Iraq at short notice. Do not rely on FCDO being able to help you evacuate in an emergency."]},{"k":"hs","s":["Protests"]},{"k":"p","s":["Protests take place regularly across Iraq, including in and around the International Zone. Clashes between Iraqi security forces and protesters have resulted in casualties and loss of life. Avoid rallies, marches and processions, and follow the instructions of local authorities."]},{"k":"hs","s":["Curfews"]},{"k":"p","s":["Curfews and vehicle bans can be imposed at short notice, particularly during protests and civil unrest, but also around religious holidays, pilgrimages and politically sensitive times, such as elections."]},{"k":"h","s":["Crime"]},{"k":"p","s":["The proliferation of guns throughout Iraq mean they are readily available to many Iraqi citizens. Guns are frequently used to settle personal grievances, criminal acts and tribal disputes."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["It is a legal requirement to carry some form of photographic ID in Iraq. Always carry your passport or residence permit. The authorities may stop people for ID checks at checkpoints within cities and on main roads across the country. You should cooperate with officials conducting checks."]},{"k":"hs","s":["Lost and stolen passports"]},{"k":"p","s":["It is a legal requirement to publish the details of your lost or stolen passport in two local newspapers, after reporting the incident to the police. You may be refused an exit stamp until you have done so."]},{"k":"hs","s":["Ramadan"]},{"k":"p","s":["Ramadan is a holy month for Muslims. The dates vary by year and country. During this time, do not:"]},{"k":"li","s":["drink, smoke or chew gum in public in the daytime, including in your car"]},{"k":"li","s":["play loud music or dance"]},{"k":"li","s":["swear in public"]},{"k":"p","s":["Get more advice when you arrive from your tour guide, hotel or business contacts."]},{"k":"p","s":["You should also:"]},{"k":"li","s":["check opening hours of shops and restaurants"]},{"k":"li","s":["be aware that if hotels and restaurants are providing food or drink in fasting hours, they may separate you from Islamic guests, for example with screens"]},{"k":"li","s":["follow local dress codes – clothing that does not meet local dress codes may cause more offence at this time"]},{"k":"li","s":["be aware that fasting can cause tiredness, particularly during the later afternoon and early evening"]},{"k":"li","s":["be patient and show tolerance"]},{"k":"hs","s":["The Arba’-een"]},{"k":"p","s":["The Arba’-een, an annual pilgrimage that attracts millions of pilgrims to Iraq, usually occurs between August and September."]},{"k":"p","s":["If you travel to Iraq during the pilgrimage, ensure that your belongings are secure at all times. Keep copies of your passports, visas and other important documents."]},{"k":"hs","s":["Child custody"]},{"k":"p","s":["Iraqi family law is very different from UK law. Male heads of household can impose ‘travel bans’ on family members. Even if you, or your child, hold a British passport, you may be subject to Iraqi laws."]},{"k":"p","s":["If you are leaving Iraq with a child that has an Iraqi or dual-national Iraqi father you may need to show proof of parental permission to travel. This applies even if their mother is with them."]},{"k":"hs","s":["Journalists"]},{"k":"p","s":["Authorities may detain journalists using allegations of inadequate paperwork. Journalists should be extremely cautious and take adequate security measures."]},{"k":"hs","s":["Alcohol laws and bans"]},{"k":"p","s":["The import, manufacture, or selling of alcoholic drinks is punishable by fines of up to 25 million Iraqi dinars (IQD). FCDO is not aware of any instances of Iraqi officials stopping travellers carrying alcohol for personal use."]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Iraq continues to practise the death penalty for a range of crimes including:"]},{"k":"li","s":["drug trafficking"]},{"k":"li","s":["espionage"]},{"k":"li","s":["kidnapping"]},{"k":"li","s":["murder"]},{"k":"li","s":["rape"]},{"k":"li","s":["smuggling antiquities"]},{"k":"li","s":["terrorism"]},{"k":"li","s":["war crimes"]},{"k":"hs","s":["Drones"]},{"k":"p","s":["The Kurdistan Regional Government (KRG) prohibits sharing footage of drones being launched or target locations with media outlets or on social media, and violations may result in legal action."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["In July 2024, the Iraqi Parliament updated its Anti-Prostitution and Homosexuality Law which criminalises same-sex relationships, any promotion of same-sex relationships or behaviours, and bans people from changing gender. Under the amendment, same-sex relationships are now illegal and sexual acts could lead to a prison sentence between 10 to 15 years. If the Iraqi authorities consider your actions, clothing or other items to promote LGBT+ identities or prostitution, you could be imprisoned for up to seven years and fined between 10 to 15 million Iraqi dinars."]},{"k":"p","s":["Under the new law, it is illegal to have or perform gender changing surgery, unless you have approval from the courts. You could be imprisoned for up to three years."]},{"k":"p","s":["There is an increased risk of violence and threats (such as blackmail and intimidation) against anyone being thought to be part of the LGBT+ community or supporting their rights. There have been attacks against the LGBT+ community and its supporters."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Iraq, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You’ll need to have both the ",["1968 version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," and your UK driving licence with you in the car. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["Road travel within Iraq is dangerous. Driving standards are low compared to those in the UK. Road traffic accidents are frequent and often result in fatalities. Fake vehicle checkpoints have been used to launch terrorist attacks. There is also a risk of carjacking and robbery."]},{"k":"hs","s":["Air travel"]},{"k":"p","s":["When in an airport, be wary of anyone approaching you that you do not know or cannot identify. Do not accept offers from strangers for help or transport. Cooperate fully with security officials at airports and observe any additional security measures."]},{"k":"p","s":["Your transfer vehicle should be pre-arranged or provided by a trusted sponsor."]},{"k":"p","s":["Since October 2023, drone and rocket attacks have hit Coalition military installations across Iraq. Erbil International Airport has had short closures, with operations resuming after a few hours. Indirect rocket attacks have occurred against Baghdad International Airport and Erbil Airport."]},{"k":"p","s":["Flight schedules may change without notice. Contact your airline or travel company for the latest information before travelling. The ",["UK Air Safety List (ASL)","https://www.gov.uk/guidance/uk-air-safety-list"]," lists all known airlines in Iraq that do not meet international safety standards and are banned from operating commercial air services to, from, and within the UK. Check the UK Air Safety List when considering which airlines to fly with. The list is maintained by the Department for Transport, based on advice from the ",["UK Civil Aviation Authority","https://www.caa.co.uk/Commercial-Industry/Airlines/Licensing/Requirements-and-guidance/Third-Country-Operator-Certificates"],"."]},{"k":"p","s":["UK government staff working in Iraq are authorised to use aircraft operated by Iraqi Airways for internal flights on a case by case basis."]},{"k":"hs","s":["Sea travel"]},{"k":"p","s":["Ports are at high risk of attack. Be extremely cautious if you are in any type of vessel in the northern Persian Gulf. Vessels are at an increased risk of attack in:"]},{"k":"li","s":["the Gulf of Oman"]},{"k":"li","s":["Northern Arabian Sea"]},{"k":"li","s":["Gulf of Aden"]},{"k":"li","s":["Bab El Mandeb"]},{"k":"p","s":["Consider any regional tensions that may affect your route and check whether sea borders will be open before your crossing."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to prepare for and respond to ",["extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["Flash floods are common between November and March. Expect disruption to travel. Exercise caution in areas of heavy rainfall, as floods have caused loss of life."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["Earthquakes are a risk in Iraq."]},{"k":"p","s":["The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"hs","s":["Dust storms"]},{"k":"p","s":["Sand and dust storms are common during the spring and summer months. Poor visibility can create difficult driving conditions and affect flights."]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Iraq. It only covers regions where the Foreign, Commonwealth & Development Office (FCDO) has specific advice."]},{"k":"p","s":["You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/iraq"]," and ",["safety and security advice","https://www.gov.uk/foreign-travel-advice/iraq/safety-and-security"],"."]},{"k":"h","s":["Northern and western Iraq"]},{"k":"p","s":["Areas liberated from Daesh are likely to contain remnants of war and improvised explosive devices."]},{"k":"h","s":["Baghdad"]},{"k":"p","s":["Routes in and out of Baghdad and its airport may close with little or no notice. Check your routes in advance of travelling."]},{"k":"p","s":["Stay alert and follow the advice of local authorities."]},{"k":"p","s":["Avoid political gatherings and large crowds. Reduce your movement around banks, restaurants, and shopping malls. Follow instructions from security officials."]},{"k":"h","s":["Kurdistan Region of Iraq (KRI)"]},{"k":"p","s":["Routes in and out of the KRI, including Erbil International Airport and Sulaymaniyah International Airport, may close at short notice. If the airport closes, expect significant delays at land border crossings. Check your routes in advance of travelling."]},{"k":"p","s":["Stay alert and follow the advice of local authorities. Stay away from political gatherings and large crowds."]},{"k":"p","s":["Foreign nationals crossing the border illegally from neighbouring countries into the Kurdistan Region of Iraq have been arrested for immigration offences. Prosecuted offenders could face a prison sentence of up to 5 years or fines of several thousand US dollars."]},{"k":"h","s":["Desert areas"]},{"k":"p","s":["Infrastructure in terms of communications, healthcare and security in remote desert areas will be limited."]},{"k":"h","s":["Basra"]},{"k":"p","s":["Protests are common in Basra. Stay alert, monitor media reports and keep up to date with this travel advice."]},{"k":"h","s":["Land borders"]},{"k":"p","s":["Border crossing points with countries neighbouring Iraq may close with little or no notice. If crossing the border, stick to main roads and ensure you use official designated border crossings."]},{"k":"h","s":["Landmines"]},{"k":"p","s":["Landmines and other unexploded weapons are present in some rural and desert areas of Iraq, particularly in border areas. A number of people are killed each year. Some areas have warning signs, but not all. If you are travelling to rural or desert areas take local advice and stick to well trodden paths and well driven tracks, and do not pick up metal objects."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 122 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Iraq","https://travelhealthpro.org.uk/country/108/iraq#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Iraq","https://travelhealthpro.org.uk/country/108/iraq"],", including:"]},{"k":"li","s":["Crimean-Congo haemorrhagic fever"]},{"k":"li","s":["malaria"]},{"k":"li","s":["poor air quality from dust and sand storms"]},{"k":"p","s":["Altitude sickness is a risk in parts of Iraq. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Iraq"]},{"k":"p","s":["FCDO has a ",["list of medical providers in Iraq","https://www.gov.uk/government/publications/iraq-doctors-and-medical-facilities"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Iraq"]},{"k":"p","s":["Ambulance: 122"]},{"k":"p","s":["Fire: 115"]},{"k":"p","s":["Police: 911"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Iraq"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=iraq"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=iraq"]," in Iraq"]},{"k":"li","s":["dealing with a ",["death in Iraq","https://www.gov.uk/government/publications/iraq-bereavement-information-pack"]]},{"k":"li","s":["being ",["arrested or imprisoned in Iraq","https://www.gov.uk/government/publications/information-pack-for-british-prisoners-in-iraq-not-including-kurdistan"]," and being ",["arrested or imprisoned in the Kurdistan Region of Iraq","https://www.gov.uk/government/publications/information-pack-for-british-prisoners-in-kurdistan-region"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/iraq/british-embassy-baghdad"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/iraq/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Iraq","https://www.gov.uk/government/publications/overseas-business-risk-iraq"]," on how to manage political, economic, and business security-related risks."]}],"chars":24331,"change":"Updated information about regional tensions (‘Warnings and insurance’ page)."}};
